        Quest("CH2-013",2,13,"Constantino's Strange Request",category="Khorinis - Craftsmen's Quarter",giver = "Constantino",location="Khorinis - Craftsmen's Quarter",prerequisites="Chapter 2. Consider completing Ignaz's Experiment and Field Predator before this quest triggers subsequent events.",summary="Fetch a special bloodfly-stinger poison sample for Constantino; ordinary crafted poison will not satisfy him.",walkthroughSteps=listOf("Ask Constantino in Chapter 2 about his unusual alchemical request.","Obtain the quest-specific bloodfly poison either from Fregyal or Baal Tyon for 1,000 gold, or from the wine cave in the eastern forest.","For the wine cave route, get Mole Rat Fat from Martin or Zuris, another quest, or the hold of the paladins' ship.","Use the fat to open the cave grate, defeat the named goblin Mirbl and pick the chest holding the poison.","Return the specific poison sample to Constantino."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Ordinary crafted poison will not work. This chain can eventually lead to Ignaz's death, so buy any needed Oblivion scrolls in advance. Source: https://rpgrussia.com/threads/strannaja-prosba-konstantino.66847/",searchTags=listOf("constantino's strange request","khorinis - craftsmen's quarter","local quest giver in khorinis - craftsmen's quarter")),
        Quest("CH2-014",2,14,"Strange Merchant",category="Khorinis - Craftsmen's Quarter",giver="Thorben",location="Khorinis - Craftsmen's Quarter",prerequisites="Chapter 2; complete earlier quests in the same area/faction if the dialogue is not yet available.",summary="Find Thorben's missing niece Gritta and return her safely to Khorinis.",walkthroughSteps=listOf("Talk to Thorben about Gritta's disappearance.","Either pay Thorben 500 gold, or investigate the bandit encampment in the forest visited during Bartok's hunt.","Defeat the bandits at the forest camp and find Gritta in a tent.","Escort her to the city gate and return to Thorben to finish the quest."),reward="Reward varies by quest/build; exact values should be taken from the current in-game dialogue or source page.",warnings="Make a manual save before using one-way portals, ritual objects or major temple mechanisms.",searchTags=listOf("strange merchant","khorinis - craftsmen's quarter","local quest giver in khorinis - craftsmen's quarter","thorben")),
